<!DOCTYPE html>
<html lang="en" style="margin: 0; padding: 0; overflow: hidden; background: #0a0a1a; height: 100vh; width: 100vw;">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, user-scalable=no, minimum-scale=1.0, maximum-scale=1.0">
    <title>Lotte Tower - Architectural Data Sculpture</title>
    <style>
        body {
            font-family: 'Courier New', monospace;
            color: #e0e0e0;
            overflow: hidden;
            touch-action: none;
        }
        #info {
            position: absolute;
            top: 20px;
            left: 20px;
            width: 300px;
            background: rgba(0, 0, 0, 0.7);
            padding: 15px;
            border: 1px solid #333;
            font-size: 19px;
            line-height: 1.6;
            z-index: 100;
            max-height: 80vh;
            overflow-y: auto;
        }
        #controls {
            position: absolute;
            top: 20px;
            right: 20px;
            background: rgba(0, 0, 0, 0.7);
            padding: 15px;
            border: 1px solid #333;
            font-size: 19px;
            z-index: 100;
        }
        button {
            background: #1a1a2e;
            color: #e0e0e0;
            border: 1px solid #333;
            padding: 8px 12px;
            margin: 5px 0;
            cursor: pointer;
            font-size: 19px;
            transition: all 0.2s;
        }
        button:hover {
            background: #2a2a4e;
        }
        .keybinds {
            margin-top: 15px;
            font-size: 19px;
        }
        .keybinds span {
            margin-right: 10px;
        }
        #canvas-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            justify-content: center;
            align-items: center;
        }
        #loading {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: #e0e0e0;
            font-size: 19px;
            z-index: 200;
        }
    </style>
</head>
<body>
    <div id="info">
        <h2>Lotte Tower Data Sculpture</h2>
        <p>Architectural visualization using real-time 3D data rendering. Explore the structural geometry through interactive camera controls.</p>
        <p>Current mode: <span id="mode-display">Structural Analysis</span></p>
        <p>Press <strong>H</strong> for help, <strong>M</strong> to toggle modes, <strong>R</strong> to reset view</p>
    </div>

    <div id="controls">
        <button id="reset-view">Reset Camera</button>
        <button id="toggle-wireframe">Toggle Wireframe</button>
        <button id="toggle-labels">Toggle Structural Labels</button>
        <div class="keybinds">
            <span>W/A/S/D</span> - Move camera
            <span>Mouse Drag</span> - Rotate view
            <span>Mouse Wheel</span> - Zoom
            <span>Shift+Drag</span> - Pan
        </div>
    </div>

    <div id="canvas-container">
        <canvas id="render-canvas"></canvas>
    </div>

    <div id="loading">Initializing 3D environment... Loading structural data...</div>

    <script>
        // Load Three.js from local model runtime
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js';
        script.integrity = 'sha256-mYkA2rNjSPQnWGtC+JjTQGpq2lY08zZ3c4mFco=';
        script.crossOrigin = 'anonymous';
        document.head.appendChild(script);

        const scriptOrbit = document.createElement('script');
        scriptOrbit.src = 'https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js';
        scriptOrbit.integrity = 'sha256-6XMZvx+oXrM4v7HYlqwXjQ+JCZ/7DQHQ3R4y0xWkQ';
        scriptOrbit.crossOrigin = 'anonymous';
        document.head.appendChild(scriptOrbit);

        // Main application
        let container, camera, scene, renderer, controls;
        let towerGeometry, towerMaterial, towerMesh;
        let structuralLines = [];
        let labels = [];
        let wireframeMode = false;
        let showLabels = true;
        let currentMode = 'structural';

        // Initialize when Three.js is loaded
        window.addEventListener('load', init);
        function init() {
            container = document.getElementById('render-canvas');
            container.style.width = '100%';
            container.style.height = '100%';

            // Create scene
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x0a0a1a);

            // Create camera
            camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 10000);
            camera.position.set(500, 500, 500);

            // Create renderer with proper pixel ratio
            renderer = new THREE.WebGLRenderer({ antialias: true, canvas: container });
            renderer.setPixelRatio(window.devicePixelRatio);
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.outputEncoding = THREE.sRGBEncoding;
            renderer.toneMapping = THREE.ACESFilmicToneMapping;
            renderer.toneMappingExposure = 1.2;

            // Add orbit controls with keyboard support
            controls = new THREE.OrbitControls(camera, renderer.domElement);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.screenSpacePanning = false;
            controls.minDistance = 100;
            controls.maxDistance = 5000;
            controls.maxPolarAngle = Math.PI * 0.95;

            // Enable keyboard controls
            controls.keys = {
                LEFT: 'ArrowLeft',
                UP: 'ArrowUp',
                RIGHT: 'ArrowRight',
                BOTTOM: 'ArrowDown'
            };

            // Handle window resize
            window.addEventListener('resize', onWindowResize);

            // Create Lotte Tower structure
            createTowerStructure();

            // Add lights
            const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(1, 1, 1);
            scene.add(directionalLight);

            // Add axes helper
            const axesHelper = new THREE.AxesHelper(200);
            scene.add(axesHelper);

            // Add event listeners
            document.addEventListener('keydown', onKeyDown);

            // Start animation loop
            animate();

            // Hide loading message
            document.getElementById('loading').style.display = 'none';
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function createTowerStructure() {
            // Main tower base (simplified parametric structure)
            const baseHeight = 100;
            const baseWidth = 150;
            const baseDepth = 150;

            // Create parametric tower geometry
            const towerPoints = [];
            const segments = 20;

            // Generate spiral structure
            for (let i = 0; i <= segments; i++) {
                const angle = (i / segments) * Math.PI * 2;
                const radius = 50 + (i / segments) * 100;
                const height = (i / segments) * baseHeight;

                towerPoints.push(
                    new THREE.Vector3(
                        radius * Math.cos(angle),
                        height,
                        radius * Math.sin(angle)
                    )
                );
            }

            // Create tube geometry for the tower
            const tubeGeometry = new THREE.TubeGeometry(
                new THREE.CatmullRomCurve3(towerPoints),
                segments * 2,
                10,
                8,
                false
            );

            // Create material with gradient
            const gradient = new THREE.CanvasTexture(generateGradient());
            const material = new THREE.MeshPhongMaterial({
                map: gradient,
                transparent: true,
                opacity: 0.9,
                side: THREE.DoubleSide,
                shininess: 30
            });

            // Create tower mesh
            towerMesh = new THREE.Mesh(tubeGeometry, material);
            towerMesh.rotation.x = Math.PI / 2;
            scene.add(towerMesh);

            // Add structural lines (simplified)
            addStructuralLines();

            // Add observation deck
            addObservationDeck();

            // Add labels
            addStructuralLabels();
        }

        function generateGradient() {
            const canvas = document.createElement('canvas');
            canvas.width = 256;
            canvas.height = 1;
            const context = canvas.getContext('2d');

            const gradient = context.createLinearGradient(0, 0, 256, 0);
            gradient.addColorStop(0, '#1a1a3a');
            gradient.addColorStop(0.5, '#2a2a5a');
            gradient.addColorStop(1, '#1a1a3a');

            context.fillStyle = gradient;
            context.fillRect(0, 0, 256, 1);

            return canvas;
        }

        function addStructuralLines() {
            // Simplified structural lines (would be replaced with actual data in production)
            const colors = [
                new THREE.Color(0xff5555),
                new THREE.Color(0x55ff55),
                new THREE.Color(0x5555ff),
                new THREE.Color(0xffff55)
            ];

            // Vertical supports
            for (let i = 0; i < 8; i++) {
                const angle = (i / 8) * Math.PI * 2;
                const radius = 100 + Math.random() * 50;
                const height = 100 + Math.random() * 200;

                const start = new THREE.Vector3(
                    radius * Math.cos(angle),
                    0,
                    radius * Math.sin(angle)
                );

                const end = new THREE.Vector3(
                    radius * Math.cos(angle),
                    height,
                    radius * Math.sin(angle)
                );

                const line = new THREE.Line(
                    new THREE.BufferGeometry().setFromPoints([start, end]),
                    new THREE.LineBasicMaterial({
                        color: colors[i % colors.length],
                        linewidth: 2
                    })
                );

                scene.add(line);
                structuralLines.push(line);
            }

            // Horizontal connections
            for (let i = 0; i < 12; i++) {
                const angle1 = (i / 12) * Math.PI * 2;
                const angle2 = ((i + 3) / 12) * Math.PI * 2;
                const radius = 100 + Math.random() * 50;
                const height = 50 + Math.random() * 150;

                const start = new THREE.Vector3(
                    radius * Math.cos(angle1),
                    height,
                    radius * Math.sin(angle1)
                );

                const end = new THREE.Vector3(
                    radius * Math.cos(angle2),
                    height,
                    radius * Math.sin(angle2)
                );

                const line = new THREE.Line(
                    new THREE.BufferGeometry().setFromPoints([start, end]),
                    new THREE.LineBasicMaterial({
                        color: colors[(i + 4) % colors.length],
                        linewidth: 2
                    })
                );

                scene.add(line);
                structuralLines.push(line);
            }
        }

        function addObservationDeck() {
            const deckHeight = 450;
            const deckRadius = 120;
            const deckSegments = 32;

            // Create deck platform
            const deckGeometry = new THREE.CylinderGeometry(
                deckRadius - 5,
                deckRadius - 5,
                10,
                deckSegments,
                1
            );
            deckGeometry.rotateX(Math.PI / 2);
            deckGeometry.translate(0, deckHeight, 0);

            const deckMaterial = new THREE.MeshPhongMaterial({
                color: 0x333333,
                transparent: true,
                opacity: 0.7
            });

            const deck = new THREE.Mesh(deckGeometry, deckMaterial);
            scene.add(deck);

            // Create deck railing
            const railingGeometry = new THREE.TorusGeometry(
                deckRadius - 2,
                3,
                deckSegments,
                10
            );
            railingGeometry.rotateX(Math.PI / 2);
            railingGeometry.translate(0, deckHeight + 5, 0);

            const railingMaterial = new THREE.MeshPhongMaterial({
                color: 0x555555,
                side: THREE.DoubleSide
            });

            const railing = new THREE.Mesh(railingGeometry, railingMaterial);
            scene.add(railing);
        }

        function addStructuralLabels() {
            const loader = new THREE.FontLoader();
            loader.load('https://threejs.org/examples/fonts/helvetiker_regular.typeface.json', function(font) {
                const textGeometry = new THREE.TextGeometry('LOTTE TOWER', {
                    font: font,
                    size: 20,
                    height: 5,
                    curveSegments: 12,
                    bevelEnabled: true,
                    bevelThickness: 2,
                    bevelSize: 1,
                    bevelOffset: 0,
                    bevelSegments: 5
                });

                textGeometry.computeBoundingBox();
                const centerOffset = -0.5 * (textGeometry.boundingBox.max.x - textGeometry.boundingBox.min.x);

                const textMaterial = new THREE.MeshPhongMaterial({
                    color: 0xffff00,
                    transparent: true,
                    opacity: 0.9
                });

                const textMesh = new THREE.Mesh(textGeometry, textMaterial);
                textMesh.position.set(0, 500, 0);
                textMesh.rotation.x = Math.PI / 2;
                textMesh.position.x += centerOffset;
                scene.add(textMesh);
                labels.push(textMesh);

                // Add more labels for structural elements
                const labelData = [
                    { text: 'BASE', position: [0, 0, 0], size: 15 },
                    { text: 'SUPPORT', position: [100, 200, 100], size: 12 },
                    { text: 'DECK', position: [0, 450, 0], size: 18 },
                    { text: 'PEAK', position: [0, 500, 0], size: 16 }
                ];

                labelData.forEach(data => {
                    const textGeometry = new THREE.TextGeometry(data.text, {
                        font: font,
                        size: data.size,
                        height: 3,
                        curveSegments: 12,
                        bevelEnabled: true,
                        bevelThickness: 1,
                        bevelSize: 0.5,
                        bevelOffset: 0,
                        bevelSegments: 3
                    });

                    textGeometry.computeBoundingBox();
                    const centerOffset = -0.5 * (textGeometry.boundingBox.max.x - textGeometry.boundingBox.min.x);

                    const textMaterial = new THREE.MeshPhongMaterial({
                        color: 0x00ffff,
                        transparent: true,
                        opacity: 0.8
                    });

                    const textMesh = new THREE.Mesh(textGeometry, textMaterial);
                    textMesh.position.set(...data.position);
                    textMesh.position.x += centerOffset;
                    textMesh.rotation.x = Math.PI / 2;
                    scene.add(textMesh);
                    labels.push(textMesh);
                });
            });
        }

        function onKeyDown(event) {
            switch(event.key.toLowerCase()) {
                case 'h':
                    alert('Controls:\n' +
                          'W/A/S/D - Move camera\n' +
                          'Mouse Drag - Rotate view\n' +
                          'Mouse Wheel - Zoom\n' +
                          'Shift+Drag - Pan\n' +
                          'R - Reset view\n' +
                          'M - Toggle visualization mode\n' +
                          'L - Toggle structural labels');
                    break;
                case 'm':
                    toggleVisualizationMode();
                    break;
                case 'r':
                    resetCamera();
                    break;
                case 'l':
                    showLabels = !showLabels;
                    labels.forEach(label => {
                        label.visible = showLabels;
                    });
                    document.getElementById('toggle-labels').textContent =
                        showLabels ? 'Hide Structural Labels' : 'Show Structural Labels';
                    break;
            }
        }

        function toggleVisualizationMode() {
            currentMode = currentMode === 'structural' ? 'aesthetic' : 'structural';

            if (currentMode === 'structural') {
                // Show structural elements
                structuralLines.forEach(line => line.visible = true);
                towerMesh.material.opacity = 0.9;
                document.getElementById('mode-display').textContent = 'Structural Analysis';
            } else {
                // Show aesthetic view
                structuralLines.forEach(line => line.visible = false);
                towerMesh.material.opacity = 0.7;
                document.getElementById('mode-display').textContent = 'Aesthetic View';
            }
        }

        function resetCamera() {
            controls.reset();
            camera.position.set(500, 500, 500);
            camera.lookAt(0, 0, 0);
        }

        // UI Controls
        document.getElementById('reset-view').addEventListener('click', resetCamera);

        document.getElementById('toggle-wireframe').addEventListener('click', function() {
            wireframeMode = !wireframeMode;
            if (wireframeMode) {
                towerMesh.material.wireframe = true;
                this.textContent = 'Show Solid View';
            } else {
                towerMesh.material.wireframe = false;
                this.textContent = 'Show Wireframe';
            }
        });

        document.getElementById('toggle-labels').addEventListener('click', function() {
            showLabels = !showLabels;
            labels.forEach(label => {
                label.visible = showLabels;
            });
            this.textContent = showLabels ? 'Hide Structural Labels' : 'Show Structural Labels';
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }
    </script>
</body>
</html>
